import bpy, bmesh, math
from mathutils import Vector, Matrix
bpy.ops.wm.read_factory_settings(use_empty=True)
sc = bpy.context.scene

def mat(name, col, rough=0.3, metal=0.0, coat=0.0):
    m = bpy.data.materials.new(name); m.use_nodes=True
    b = m.node_tree.nodes["Principled BSDF"]
    b.inputs["Base Color"].default_value = (*col,1)
    b.inputs["Roughness"].default_value = rough
    b.inputs["Metallic"].default_value = metal
    if coat: b.inputs["Coat Weight"].default_value = coat
    return m
M = {
 'yellow': mat("Yellow Plastic",(0.93,0.62,0.02),0.22,coat=0.3),
 'black': mat("Black Plastic",(0.012,0.012,0.013),0.35),
 'blackm': mat("Black Matte",(0.02,0.02,0.022),0.6),
 'white': mat("White Plastic",(0.85,0.85,0.83),0.25),
 'chrome': mat("Chrome",(0.85,0.85,0.85),0.12,metal=1.0),
 'dark': mat("Interior Dark",(0.005,0.005,0.005),0.7),
 'seam': mat("Seam",(0.35,0.22,0.01),0.5),
}

def link(ob, m=None, smooth=True):
    sc.collection.objects.link(ob)
    if m: ob.data.materials.append(m)
    if smooth and ob.type=='MESH':
        for p in ob.data.polygons: p.use_smooth=True
    return ob

def lathe(name, prof, m, seg=96, axis='Z'):
    bm = bmesh.new()
    rings=[]
    for i,(r,z) in enumerate(prof):
        ring=[]
        if r<1e-6:
            ring=[bm.verts.new((0,0,z))]*seg
        else:
            for k in range(seg):
                a=2*math.pi*k/seg
                ring.append(bm.verts.new((r*math.cos(a), r*math.sin(a), z)))
        rings.append(ring)
    for i in range(len(rings)-1):
        A,B=rings[i],rings[i+1]
        for k in range(seg):
            vs=[A[k],A[(k+1)%seg],B[(k+1)%seg],B[k]]
            uniq=[]
            for v in vs:
                if v not in uniq: uniq.append(v)
            if len(uniq)>=3: bm.faces.new(uniq)
    bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    me=bpy.data.meshes.new(name); bm.to_mesh(me); bm.free()
    ob=bpy.data.objects.new(name,me)
    return link(ob,m)

def smoothprof(pts, n=6):
    # catmull-rom-ish densify
    out=[]
    for i in range(len(pts)-1):
        p0=Vector(pts[max(i-1,0)]); p1=Vector(pts[i]); p2=Vector(pts[i+1]); p3=Vector(pts[min(i+2,len(pts)-1)])
        for s in range(n):
            t=s/n
            v=0.5*((2*p1)+(-p0+p2)*t+(2*p0-5*p1+4*p2-p3)*t*t+(-p0+3*p1-3*p2+p3)*t**3)
            out.append((max(v.x,0),v.y))
    out.append(pts[-1])
    return out

